const item = "Notebook";

function total(quantity: number, cents: number): number {
  return quantity * cents;
}

console.log(item, total(3, 275));

interface Entry {
  readonly id: string;
  label: string;
  score?: number;
}

function describe(entry: Entry): string {
  return entry.label + ": " + (entry.score ?? "pending");
}

console.log(describe({ id: "a1", label: "Arrays" }));

type Result =
  | { state: "ok"; score: number }
  | { state: "error"; message: string };

function label(result: Result): string {
  switch (result.state) {
    case "ok": return "Score: " + result.score;
    case "error": return "Error: " + result.message;
  }
}

console.log(label({ state: "ok", score: 8 }));

function read<T, K extends keyof T>(record: T, key: K): T[K] {
  return record[key];
}

const score = read({ label: "Arrays", score: 9 }, "score");
console.log(score.toFixed(1));

interface Note {
  id: string;
  title: string;
  body: string;
}

type NotePatch = Partial<Pick<Note, "title" | "body">>;

function update(note: Note, patch: NotePatch): Note {
  return { ...note, ...patch };
}

console.log(update({ id: "1", title: "Draft", body: "" }, { title: "Ready" }));

type Score = { points: number };

function isScore(value: unknown): value is Score {
  return typeof value === "object" && value !== null &&
    "points" in value && typeof value.points === "number" &&
    Number.isFinite(value.points);
}

const decoded: unknown = JSON.parse('{"points":8}');
if (isScore(decoded)) console.log(decoded.points);

export type Task = { id: string; complete: boolean };

export async function complete(task: Task): Promise<Task> {
  return { ...task, complete: true };
}

complete({ id: "1", complete: false }).then(console.log);
